inlineScript.scriptBlock:
this.setDrawee = function(value,path){
	if(!value) return;
	if(path == "address1"){
		this.context.options.Drawee.get("value").set("address1", value.slice(0, 35));
		this.context.options.Drawee.get("value").set("address2", value.slice(35, 70));
		this.context.options.Drawee.get("value").set("address3", value.slice(70, 200))
	}
	this.context.options.Drawee.get("value").set(path, value)
}

this.collectingBankRefVIS  = function()
{

	if(this.context.options.requestType.get("value") == "amend" || this.context.options.requestType.get("value") == "recreate" ){
	
		if( this.context.options.isChecker && this.context.options.isChecker.get("value") == true){
			this.context.options.bankRefVIS.set("value", "READONLY");
		}else{
			this.context.options.bankRefVIS.set("value", "EDITABLE");
		}
	}else{
		this.context.options.bankRefVIS.set("value", "None");
	}

}


